<template>
  <ViewShell title="用户与权限" :tag="`${users.length} 个账号`" :icon="TeamOutlined">
    <section class="view-card user-panel"><div class="manage-toolbar"><div><h2 class="view-card__title"><TeamOutlined /> 平台账号</h2><p class="manage-subtitle">管理登录账号、权限等级和运维人员访问范围。</p></div><button class="primary-btn" type="button" @click="openCreate">新增账号</button></div><div v-if="error" class="manage-error">{{ error }}</div><div class="table-wrap"><table class="manage-table"><thead><tr><th>账号</th><th>权限等级</th><th>角色说明</th><th>操作</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><span class="user-avatar">{{ (user.username || '管').slice(0, 1).toUpperCase() }}</span><strong>{{ user.username }}</strong></td><td><span class="level-tag">Level {{ user.level }}</span></td><td>{{ roleText(user.level) }}</td><td><button type="button" @click="openEdit(user)">编辑</button><button type="button" class="danger-link" @click="remove(user)">删除</button></td></tr><tr v-if="!users.length"><td colspan="4" class="manage-empty">暂无账号</td></tr></tbody></table></div></section>
    <section class="view-card permission-note"><h2 class="view-card__title"><SafetyCertificateOutlined /> 权限说明</h2><div class="permission-grid"><div><b>Level 1</b><span>值守人员：查看实时数据、处理通知、使用业务页面。</span></div><div><b>Level 2</b><span>运维人员：包含值守权限，可维护设备与监测参数。</span></div><div><b>Level 3</b><span>系统管理员：包含全部管理功能，可维护账号和库区档案。</span></div></div></section>
    <div v-if="editing" class="modal-backdrop" @click.self="editing = null"><form class="manage-modal" @submit.prevent="save"><div class="modal-head"><div><h2>{{ editing.id ? '编辑账号' : '新增账号' }}</h2><p>密码会沿用当前登录模块的账号表。</p></div><button type="button" class="close-btn" @click="editing = null">×</button></div><div class="form-grid"><label>用户名<input v-model.trim="editing.username" required autocomplete="off" /></label><label>权限等级<select v-model.number="editing.level"><option v-if="editing.level === 0" :value="0">Level 0 · 原系统管理员</option><option :value="1">Level 1 · 值守人员</option><option :value="2">Level 2 · 运维人员</option><option :value="3">Level 3 · 系统管理员</option></select></label><label class="span-2">登录密码<input v-model="editing.password" type="password" :required="!editing.id" minlength="6" :placeholder="editing.id ? '留空保留原密码' : '至少 6 位'" autocomplete="new-password" /></label></div><div class="modal-foot"><button type="button" class="plain-btn" @click="editing = null">取消</button><button class="primary-btn" type="submit">保存账号</button></div></form></div>
  </ViewShell>
</template>

<script setup>
import { onMounted, ref } from 'vue'
import { SafetyCertificateOutlined, TeamOutlined } from '@ant-design/icons-vue'
import ViewShell from './ViewShell.vue'
import { addUser, deleteUser, listUsers, updateUser } from '../api/manageApi.js'
const users = ref([]); const editing = ref(null); const error = ref('')
const roleText = (level) => ({ 0: '原系统管理员', 1: '值守人员', 2: '运维人员', 3: '系统管理员' }[level] || '普通用户')
async function load() { try { const result = await listUsers(); users.value = result.data || [] } catch (e) { error.value = e.message } }
function openCreate() { editing.value = { username: '', password: '', level: 1 } }
function openEdit(user) { editing.value = { id: user.id, username: user.username, password: '', level: user.level } }
async function save() { try { if (editing.value.id) await updateUser(editing.value); else await addUser(editing.value); editing.value = null; await load() } catch (e) { error.value = e.message } }
async function remove(user) { if (!window.confirm(`确定删除账号“${user.username}”吗？`)) return; try { await deleteUser(user.id); await load() } catch (e) { error.value = e.message } }
onMounted(load)
</script>

<style scoped>
.user-panel{min-height:400px}.manage-toolbar{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:18px}.manage-subtitle{margin:-8px 0 0;color:#7890a4;font-size:11px}.primary-btn,.plain-btn{height:34px;padding:0 14px;border:0;border-radius:8px;font-size:12px;cursor:pointer}.primary-btn{background:#1679d1;color:#fff}.plain-btn{border:1px solid #d8e5ee;background:#fff;color:#557188}.manage-error{margin-bottom:12px;padding:10px 12px;border-radius:8px;background:#fff2f1;color:#b64c4a;font-size:12px}.table-wrap{overflow:auto}.manage-table{width:100%;border-collapse:collapse;color:#557188;font-size:11px}.manage-table th{padding:11px 10px;color:#8198aa;background:#f5f9fb;font-weight:600;text-align:left}.manage-table td{padding:12px 10px;border-bottom:1px solid #edf2f5}.manage-table td:first-child{display:flex;align-items:center;gap:9px;color:#294b66}.manage-table td strong{font-size:12px}.manage-table button{margin-right:11px;border:0;background:none;color:#247cc2;font-size:11px;cursor:pointer}.manage-table .danger-link{color:#d06462}.user-avatar{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:50%;background:#e6f4fd;color:#247fc1;font-size:12px}.level-tag{padding:4px 8px;border-radius:6px;background:#edf7fd;color:#3189b6;font-size:10px}.manage-empty{padding:30px!important;text-align:center;color:#91a4b2}.permission-note{margin-top:14px}.permission-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.permission-grid>div{padding:13px;border:1px solid #e4edf3;border-radius:9px;background:#fbfdfe}.permission-grid b,.permission-grid span{display:block}.permission-grid b{color:#2d6488;font-size:12px}.permission-grid span{margin-top:5px;color:#7d93a4;font-size:10px;line-height:1.6}.modal-backdrop{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(9,35,58,.4)}.manage-modal{width:min(500px,100%);padding:22px;border-radius:15px;background:#fff;box-shadow:0 20px 60px rgba(13,53,82,.25)}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.modal-head h2{margin:0;color:#173955;font-size:18px}.modal-head p{margin:4px 0 0;color:#8298a9;font-size:11px}.close-btn{border:0;background:none;color:#8197a7;font-size:24px;cursor:pointer}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.form-grid label{display:flex;flex-direction:column;gap:5px;color:#617b90;font-size:11px}.form-grid input,.form-grid select{height:35px;padding:0 9px;border:1px solid #dce8f0;border-radius:8px;background:#fbfdfe;color:#284967;font:inherit;font-size:12px;outline:none}.span-2{grid-column:span 2}.modal-foot{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}@media(max-width:700px){.manage-toolbar{flex-direction:column}.permission-grid,.form-grid{grid-template-columns:1fr}.span-2{grid-column:auto}}
</style>
